import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";

const typingLines = [
  "Built by students, for students.",
  "Turn science into something you actually enjoy.",
  "Study smarter with SciPet AI and live help.",
];

function Home() {
  const [currentLineIndex, setCurrentLineIndex] = useState(0);
  const [displayedText, setDisplayedText] = useState("");

  useEffect(() => {
    const text = typingLines[currentLineIndex];
    setDisplayedText("");

    let charIndex = 0;
    const speed = 45;

    const interval = setInterval(() => {
      setDisplayedText(text.slice(0, charIndex + 1));
      charIndex++;
      if (charIndex === text.length) {
        clearInterval(interval);
        setTimeout(() => {
          setCurrentLineIndex((prev) => (prev + 1) % typingLines.length);
        }, 1500);
      }
    }, speed);

    return () => clearInterval(interval);
  }, [currentLineIndex]);

  return (
    <section className="page home-page fade-in">
      <div className="hero">
        <div className="hero-text slide-up">
          <h1>SciHub: Your Science Learning Hub</h1>
          <p className="typing-line">{displayedText}</p>
          <p>
            Join live tutoring, play science games, complete smart worksheets, and get
            instant feedback — all supported by SciPet, your AI study buddy.
          </p>

          <div className="hero-actions">
            <Link to="/signup" className="primary-btn">
              Get started free
            </Link>
            <Link to="/features" className="secondary-btn">
              Explore features
            </Link>
          </div>
        </div>

        <div className="hero-visual fade-in" aria-hidden="true">
          <div className="orbit" />
          <div className="orbit-small" />
          <div className="atom-core" />
        </div>
      </div>

      <section className="home-highlights slide-up">
        <div className="card">
          <h2>Live Support</h2>
          <p>
            Join scheduled tutoring and group study sessions to ask questions and learn with
            others in real time.
          </p>
        </div>
        <div className="card">
          <h2>Smart Practice</h2>
          <p>
            Complete science worksheets and view instant analysis of your strengths and areas
            to review.
          </p>
        </div>
        <div className="card">
          <h2>Science Games</h2>
          <p>
            Make physics, chemistry, and biology more fun with quick games and challenges that
            keep you engaged.
          </p>
        </div>
      </section>
    </section>
  );
}

export default Home;
